Given an index $1\leq i\leq k$, 
        parameters $W,V\in \mathbb{R}^{d\times k}$, and 
        constants $\upgamma\in (0,\nicefrac{1}{2})$ and $R\geq 2$, 
        let $\ensuremath{\mathscr{E}}=\ensuremath{\mathscr{E}}_{i,\upgamma,R}$ be the following event 
        \[
           {\left\{ x \in \mathbb{R}^d :  1 ~\leq~ 
            \frac{{x{^\top} \widehat{w}_i}}{
                R\sqrt{\log{\nicefrac{1}{\upgamma}}}
            }\,,
            ~
            \frac{{x{^\top} \widehat{u}}}{
                2\sqrt{\log{\nicefrac{1}{\upgamma}}}
            }
            ~\leq~ 2 \right\}\,.}
        \]
        Here {$\widehat{w}_i$ is the unit vector parallel to $w_i$,}
        $u\coloneqq v_i - {(v_i^\top \widehat{w}_i}) \cdot \widehat{w}_i$ is the component of $v_i$ orthogonal to $w_i${, and $\widehat{u}$ is its corresponding unit vector}.
        Further, in the special case, where $v_i$ is parallel to $w_i$ (and, hence, $u=0$), the definition of $\ensuremath{\mathscr{E}}$ omits the bound on ${x^\top \widehat{u}}.$

\[
        \left| 
            \Pr\ensuremath{\left[y_{\max, V} \leq 0\mid \ensuremath{\mathscr{E}}\right]}
            -
            \Pr\ensuremath{\left[y_{\max, W} \leq 0\mid \ensuremath{\mathscr{E}}\right]}
         \right|
        \geq 
        \frac{1}{\Pr[\ensuremath{\mathscr{E}}]}
        \cdot {\ensuremath{\left(\frac{c}{ek}\right)}^{{O({C^2/c^2}){}}}}
        \cdot \relax{v_i-w_i}_2\,.
        \addtocounter{equation}{1}\tag{\theequation}
    \]

Fix any constants $\upgamma\in (0,\nicefrac{1}{2}]$ and $R\geq 3 + ({9C/c})$.
            Let $i$ be the index in 5.1.
            The following guarantees hold {with probability 1}
            conditioned on the event $\ensuremath{\mathscr{E}}= \ensuremath{\mathscr{E}}_{i,\upgamma,R}$ (6):
            \begin{enumerate}
                \item 
                    For any $j\neq i$,
                    $\rho_{i,V} - \rho_{j, V}\geq 3cR \cdot \sqrt{\log{\nicefrac{1}{\upgamma}}}$ and 
                    $ \rho_{i, W} - \rho_{j, W}\geq  3cR \cdot  \sqrt{\log{\nicefrac{1}{\upgamma}}}$;
                \item For each $j$,
                    $\left| \rho_{j, V} - \rho_{j, W} \right|\leq 3R \cdot \sqrt{\log{\nicefrac{1}{\upgamma}}}\cdot \relax{v_j - w_j}_2$; 
                \item Further, for the $i$ in 5.1, $\left| \rho_{i,V} - \rho_{i,W} \right|\geq \ensuremath{\left({5R/6}\right)} \cdot \sqrt{\log{\nicefrac{1}{\upgamma}}}\cdot \relax{v_i - w_i}_2$.
            \end{enumerate}

\begin{align*}
        \hspace{-2.5mm}
        &\left| 
                \Pr\ensuremath{\left[y_{\max, V} \leq 0\mid \ensuremath{\mathscr{E}}\right]}
                - \Pr\ensuremath{\left[y_{\max, W} \leq 0\mid \ensuremath{\mathscr{E}}\right]}
         \right| \\
        &= 
        \underbrace{\ensuremath{\left(
            \prod_{j}~ \Phi\ensuremath{(-\rho_{j,V}; \sigma_{j,V}^2)}
        \right)}}_{\textsf{A}}
        \cdot  
        \bigg| 
            1 - 
            \underbrace{\frac{
                \Phi\ensuremath{(-\rho_{i,W}; \sigma_{i,W}^2)}
            }{
                \Phi\ensuremath{(-\rho_{i,V}; \sigma_{i,V}^2)}
            }}_{\textsf{B}}
            \cdot 
            \underbrace{\prod_{j\neq i}~ \frac{
                \Phi\ensuremath{(-\rho_{j,W}; \sigma_{j,W}^2)}
            }{
                \Phi\ensuremath{(-\rho_{j,V}; \sigma_{j,V}^2)}
            }}_{\textsf{C}}
         \bigg|\,.
        \addtocounter{equation}{1}\tag{\theequation}
    \end{align*}

For any constants $\upgamma\in (0,\nicefrac{1}{2})$ and $R\geq 3 + ({10C/c})$, index $i$ in 5.1, and $j\neq i$
        \begin{align*}
                \frac{
                    \Phi\ensuremath{(-\rho_{i,V}; \sigma_{i,V}^2)}
                }{
                    \Phi\ensuremath{(-\rho_{i,W}; \sigma_{i,W}^2)}
                }
                &~~\notin~~ 
                \ensuremath{\left[
                    1 \pm \frac{1}{100C}\cdot 
                    \min\ensuremath{\left\{
                        1\,,
                        R \sqrt{\log{\nicefrac{1}{\upgamma}}}\cdot \relax{v_i-w_i}_2 
                    \right\}}
                \right]}\,,
                \addtocounter{equation}{1}\tag{\theequation}\\
                \frac{\Phi\ensuremath{(-\rho_{j,V}; \sigma_{j,V}^2)}}{\Phi\ensuremath{(-\rho_{j,W}; \sigma_{j,W}^2)}}
                &~~\in~~
                \ensuremath{\left[
                    1
                    \pm 10R\sqrt{\log{\nicefrac{1}{\upgamma}}}\cdot 
                    \ensuremath{\left(\relax{v_j-w_j}_2+C\relax{v_j-w_j}_2^2\right)}
                    \cdot \upgamma^{-\frac{c^2R^2}{72C^2}}
                \right]}
                \addtocounter{equation}{1}\tag{\theequation}
                \,.
        \end{align*}

\[
        \phantom{.}
        \qquad\qquad\qquad\qquad\qquad\quad~~
        \boldsymbol\NABLA^2 \ensuremath{\mathscr{L}}(W^\star) \succeq k^{-A\cdot C^2/c^2}\, I\,. 
        \qquad~~
        \text{(Strong Convexity at ${W^\star}$)}\hspace{-10mm}
        \addtocounter{equation}{1}\tag{\theequation}
    \]

For $\zeta\in [0,1)$ and $t=\zeta\cdot O\ensuremath{\left(\frac{1}{B^4k^3}\right)}$, it holds that,
            \[
                \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\ensuremath{\left[z\;\middle|\; \ensuremath{\mathscr{E}}\right]}
                \in 
                    \ensuremath{\left(1\pm \zeta\right)} 
                    \cdot 
                    \operatornamewithlimits{\mathbb{E}}\nolimits_{0}\ensuremath{\left[z\;\middle|\; \ensuremath{\mathscr{E}}\right]}
                \quad\text{and}\quad
                \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\ensuremath{[zz^\top \mid  \ensuremath{\mathscr{E}}]}
                \in 
                    \ensuremath{\left(1\pm \zeta\right)} 
                    \cdot 
                    \operatornamewithlimits{\mathbb{E}}\nolimits_{0}\ensuremath{[zz^\top \mid \ensuremath{\mathscr{E}}]}
                \,.
            \]

For function $f\colon \mathbb{R}^k\to \mathbb{R}$ and $t\in [0,1]$,
                \[
                    e^{-O\ensuremath{\left(t B^4 k^3\right)}}
                    \leq 
                    \frac{
                        \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\ensuremath{\left[f(z)\;\middle|\;  \ensuremath{\mathscr{E}}\right]} 
                    }{
                        \operatornamewithlimits{\mathbb{E}}\nolimits_{0}\ensuremath{\left[f(z)\;\middle|\;  \ensuremath{\mathscr{E}}\right]}
                    }\leq 
                    e^{O\ensuremath{\left(t B^4 k^3\right)}}\,.
                \]
